<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$id=$_GET['id']??'';$viewer=current_user($pdo);$s=$pdo->prepare("SELECT a.*,u.public_id author_public_id,u.username,u.display_name,s.public_id source_public_id,s.title,s.canonical_url,CASE WHEN a.source_version_id<>s.current_version_id THEN s.status ELSE 'current' END source_status,c.capture_type,c.selected_text,c.start_seconds,c.end_seconds,c.screenshot_target_path,c.screenshot_context_path,md.storage_path media_path,md.processing_status media_status,md.resolution_label,at.status transcript_status,at.raw_text transcript_raw,at.edited_text transcript_edited,at.provider transcript_provider,at.model transcript_model FROM annotations a JOIN users u ON u.id=a.user_id JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id LEFT JOIN media_derivatives md ON md.capture_id=c.id LEFT JOIN annotation_transcripts at ON at.annotation_id=a.id WHERE a.public_id=? AND a.visibility='public' AND a.status='published'");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Annotation not found.');}$comments=$pdo->prepare('SELECT c.body,c.created_at,u.display_name,u.username FROM comments c JOIN users u ON u.id=c.user_id WHERE c.annotation_id=? ORDER BY c.created_at ASC');$comments->execute([$a['id']]);$following=false;if($viewer&&$viewer['id']!=$a['user_id']){$q=$pdo->prepare('SELECT 1 FROM follows WHERE follower_user_id=? AND followed_user_id=?');$q->execute([$viewer['id'],$a['user_id']]);$following=(bool)$q->fetchColumn();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($a['title']?:'Annotation')?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/research.php">Research</a><?php if($viewer):?><a href="/logout.php">Sign out</a><?php else:?><a href="/login.php">Log in</a><?php endif?></nav></header><main class="panel article"><div class="meta"><strong><?=h($a['display_name'])?></strong> · @<?=h($a['username'])?> · <?=h($a['published_at'])?></div><?php if($a['source_status']==='edited'):?><div class="badge warn">Source changed after this annotation</div><?php elseif($a['source_status']==='updated'):?><div class="badge warn">Source updated since capture</div><?php endif?><?php if($viewer&&$viewer['id']!=$a['user_id']):?><p><button class="button secondary" id="follow" data-user="<?=h($a['author_public_id'])?>"><?=$following?'Following':'Follow'?></button></p><?php endif?><h1><?=h($a['text_commentary']?:'Annotation')?></h1><?php if($a['selected_text']):?><blockquote><?=h($a['selected_text'])?></blockquote><?php endif?><?php if($a['screenshot_target_path']):?><figure><img src="<?=h($a['screenshot_target_path'])?>" alt="Preserved screenshot of annotated content" style="max-width:100%;border-radius:14px"><figcaption class="meta">Snapshot preserved at annotation time.</figcaption></figure><?php endif?><?php if($a['media_path']):?><?php if($a['capture_type']==='video_clip'):?><video controls style="width:100%;max-height:480px" src="<?=h($a['media_path'])?>"></video><?php else:?><audio controls style="width:100%" src="<?=h($a['media_path'])?>"></audio><?php endif?><?php elseif(in_array($a['capture_type'],['video_clip','audio_clip'],true)):?><div class="card"><strong>Clip <?=h((string)$a['start_seconds'])?> → <?=h((string)$a['end_seconds'])?></strong><p class="meta">Derivative status: <?=h($a['media_status']?:'queued')?>. The annotation remains available while media processing is pending.</p></div><?php endif?><?php if($a['audio_commentary_path']):?><div class="card"><h2>Audio commentary</h2><audio class="wideAudio" controls src="<?=h($a['audio_commentary_path'])?>"></audio><details open><summary>Transcript · <?=h($a['transcript_status']?:'queued')?></summary><?php $transcript=$a['transcript_edited']?:$a['transcript_raw']; if($transcript):?><p id="transcriptText"><?=nl2br(h($transcript))?></p><?php else:?><p class="meta">Transcription is <?=h($a['transcript_status']?:'queued')?>.</p><?php endif?></details><?php if($viewer&&((int)$viewer['id']===(int)$a['user_id']||$viewer['role']==='admin')):?><button class="button secondary" id="editTranscript">Edit transcript</button><?php endif?></div><?php endif?><p><a href="/source.php?id=<?=h($a['source_public_id'])?>">View Annotated source page</a> · <a href="<?=h($a['canonical_url'])?>" target="_blank" rel="noopener">View original source ↗</a></p><div class="actions"><a class="button secondary" href="/file-a-claim.php?id=<?=h($a['public_id'])?>">File a claim</a></div><hr><h2>Discussion</h2><?php foreach($comments as $c):?><div class="card"><div class="meta"><strong><?=h($c['display_name'])?></strong> @<?=h($c['username'])?> · <?=h($c['created_at'])?></div><p><?=nl2br(h($c['body']))?></p></div><?php endforeach?><?php if($viewer):?><form id="commentForm" class="stack"><textarea id="commentBody" placeholder="Add to the discussion" required></textarea><button>Add comment</button></form><?php else:?><p><a href="/login.php">Log in</a> to comment.</p><?php endif?></main><?php if($viewer):?><script>const csrf=<?=json_encode(csrf_token())?>;document.querySelector('#follow')?.addEventListener('click',async e=>{const r=await fetch('/api/extension.php?action=follow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({user_id:e.currentTarget.dataset.user})});const j=await r.json();if(j.ok)e.currentTarget.textContent=j.data.following?'Following':'Follow';});document.querySelector('#commentForm')?.addEventListener('submit',async e=>{e.preventDefault();const body=document.querySelector('#commentBody').value.trim();if(!body)return;const r=await fetch('/api/extension.php?action=comment',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({annotation_id:<?=json_encode($a['public_id'])?>,body})});const j=await r.json();if(j.ok)location.reload();});document.querySelector('#editTranscript')?.addEventListener('click',async()=>{const current=<?=json_encode($a['transcript_edited']?:$a['transcript_raw']?:'')?>;const text=prompt('Correct the transcript:',current);if(text===null)return;const r=await fetch('/api/extension.php?action=transcript_edit',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({annotation_id:<?=json_encode($a['public_id'])?>,text})});const j=await r.json();if(j.ok)location.reload();});</script><?php endif?></body></html>